static void CalculateMaxDifferenceSum() {
    int n = fs.nextInt();
    List<Integer> A = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        A.add(fs.nextInt());
    }
    long ans = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            ans += Math.max(A.get(j) - A.get(i), 0);
        }
    }
    System.out.println(ans);
